-- 1. Extend exercises table with new columns
ALTER TABLE exercises
  ADD COLUMN IF NOT EXISTS category TEXT NOT NULL DEFAULT 'Strength Training',
  ADD COLUMN IF NOT EXISTS target_muscle TEXT NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS primary_muscle_slug TEXT NOT NULL DEFAULT 'mid-chest',
  ADD COLUMN IF NOT EXISTS youtube_urls TEXT[] NOT NULL DEFAULT '{}';

-- 2. Drop restrictive CHECK constraints so new movement patterns & types are allowed
ALTER TABLE exercises DROP CONSTRAINT IF EXISTS exercises_movement_pattern_check;
ALTER TABLE exercises DROP CONSTRAINT IF EXISTS exercises_exercise_type_check;

-- 3. Re-add broader constraints
ALTER TABLE exercises ADD CONSTRAINT exercises_movement_pattern_check
  CHECK (movement_pattern IS NOT NULL AND length(movement_pattern) > 0);
ALTER TABLE exercises ADD CONSTRAINT exercises_exercise_type_check
  CHECK (exercise_type IN ('compound','isolation','cardio','flexibility','sport','recovery'));

